mod solution;

fn main() {
    let cases = [
    (r#"[(1,2),(3,5),(6,7),(8,10),(12,16)]"#, r#"1-2,3-10,12-16"#),
    (r#"[(1,3),(9,10)]"#, r#"1-3,4-8,9-10"#),
    (r#"
[(1,3),(9,10)]
"#, r#"1-3,4-8,9-10"#),
    (r#"  
[(1,2),(3,5),(6,7),(8,10),(12,16)]
  "#, r#"1-2,3-10,12-16"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS insert-interval");
}
